--
-- Name: fn_relatorio_ocupacao(timestamp with time zone, timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_relatorio_ocupacao(p_inicio timestamp with time zone, p_fim timestamp with time zone, p_filme_id integer DEFAULT NULL::integer) RETURNS TABLE(sessao_id integer, filme_id integer, filme character varying, sala character varying, inicio timestamp with time zone, preco numeric, capacidade integer, vendidos integer, utilizados integer, taxa_ocupacao numeric, receita numeric)
    LANGUAGE sql STABLE
    AS $$
  WITH capacidade_sala AS (
    SELECT a.sala_id, count(*)::int AS capacidade
      FROM assentos a
     GROUP BY a.sala_id
  ),
  vendas_sessao AS (
    SELECT i.sessao_id,
           count(*)::int                                     AS vendidos,
           count(*) FILTER (WHERE i.status = 'UTILIZADO')::int AS utilizados,
           sum(i.valor)                                      AS receita
      FROM ingressos i
     WHERE i.status <> 'CANCELADO'
     GROUP BY i.sessao_id
  )
  SELECT s.id,
         f.id,
         f.titulo,
         sa.nome,
         s.inicio,
         s.preco,
         COALESCE(c.capacidade, 0),
         COALESCE(v.vendidos, 0),
         COALESCE(v.utilizados, 0),
         ROUND(COALESCE(v.vendidos, 0) * 100.0 / NULLIF(c.capacidade, 0), 2),
         COALESCE(v.receita, 0)
    FROM sessoes s
    JOIN filmes f              ON f.id = s.filme_id
    JOIN salas sa              ON sa.id = s.sala_id
    LEFT JOIN capacidade_sala c ON c.sala_id = s.sala_id
    LEFT JOIN vendas_sessao v   ON v.sessao_id = s.id
   WHERE s.inicio >= p_inicio
     AND s.inicio <  p_fim
     AND (p_filme_id IS NULL OR s.filme_id = p_filme_id)
   ORDER BY s.inicio, sa.nome;
$$;


--
-- Name: fn_trg_auditoria(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_trg_auditoria() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  VALUES (
    TG_TABLE_NAME,
    TG_OP,
    CASE WHEN TG_OP IN ('UPDATE', 'DELETE') THEN to_jsonb(OLD) END,
    CASE WHEN TG_OP IN ('INSERT', 'UPDATE') THEN to_jsonb(NEW) END,
    now()
  );
  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: fn_trg_sessao_gera_mapa(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_trg_sessao_gera_mapa() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  SELECT NEW.id, a.id, 'LIVRE', now()
    FROM assentos a
   WHERE a.sala_id = NEW.sala_id;
  RETURN NEW;
END;
$$;


--
-- Name: sp_gerar_assentos_sala(integer, integer, integer); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.sp_gerar_assentos_sala(IN p_sala_id integer, IN p_filas integer, IN p_por_fila integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_fila int;
  v_numero int;
BEGIN
  IF p_filas < 1 OR p_filas > 26 OR p_por_fila < 1 THEN
    RAISE EXCEPTION 'Layout inválido: % filas x % assentos', p_filas, p_por_fila
      USING ERRCODE = 'check_violation';
  END IF;

  IF EXISTS (SELECT 1 FROM sessoes WHERE sala_id = p_sala_id) THEN
    RAISE EXCEPTION 'A sala % já possui sessões; o layout não pode ser alterado', p_sala_id
      USING ERRCODE = 'restrict_violation';
  END IF;

  DELETE FROM assentos WHERE sala_id = p_sala_id;

  FOR v_fila IN 1..p_filas LOOP
    FOR v_numero IN 1..p_por_fila LOOP
      VALUES (p_sala_id, chr(64 + v_fila), v_numero);  -- 65 = 'A'
    END LOOP;
  END LOOP;
END;
$$;


